/* LoL Maverick Study Proyect · aplicación sin dependencias y sin cuentas. */
(()=>{'use strict';
const D=window.MAVERICK_DATA;
const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={pool:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',items:'<path d="m12 3 9 5-9 5-9-5 9-5Z"/><path d="m3 12 9 5 9-5M3 16l9 5 9-5"/>',study:'<path d="M12 6c-3-3-7-3-10-2v15c4-1 7-1 10 2 3-3 6-3 10-2V4c-3-1-7-1-10 2Zm0 0v15"/>',search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',star:'<path d="m12 3 2.8 5.6 6.2.9-4.5 4.4 1.1 6.1-5.6-2.9-5.6 2.9 1.1-6.1L3 9.5l6.2-.9L12 3Z"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',check:'<path d="m5 12 4 4L19 6"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>',plus:'<path d="M12 5v14M5 12h14"/>',trash:'<path d="M3 6h18M9 6V3h6v3M6 6l1 15h10l1-15M10 10v7m4-7v7"/>',shield:'<path d="m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6l8-3Z"/>',compare:'<path d="M4 7h16M7 4 4 7l3 3m13 7H4m13-3 3 3-3 3"/>',gem:'<path d="m7 3-5 6 10 12L22 9l-5-6H7Zm-5 6h20M7 3l5 18 5-18"/>',edit:'<path d="m15 4 5 5M4 20l5-1L21 7l-5-5L4 14v6Z"/>'};
const icon=(name,cls='')=>`<svg class="${cls}" viewBox="0 0 24 24" aria-hidden="true">${icons[name]||icons.gem}</svg>`;
const byId=id=>D.items.find(i=>i.id===String(id)),champ=id=>D.champions.find(c=>c.id===id),normalize=s=>String(s).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
const read=(key,fallback)=>{try{return JSON.parse(localStorage.getItem('maverick:'+key))??fallback;}catch{return fallback;}};
const saved={favorites:read('favorites',[]),studied:read('studied',[]),notes:read('notes',{}),build:read('build',[]),pool:read('pool',null),recents:read('recents',[]),rosterView:read('rosterView','compact')};
saved.favorites=saved.favorites.filter(id=>champ(id));saved.studied=saved.studied.filter(id=>champ(id));saved.build=saved.build.filter(id=>byId(id)).slice(0,6);
const persist=key=>{try{localStorage.setItem('maverick:'+key,JSON.stringify(saved[key]));}catch{toast('No se pudo guardar: revisa el almacenamiento del dispositivo.');}};
if(!Array.isArray(saved.pool))saved.pool=[...new Set([...saved.favorites,...saved.studied,...Object.keys(saved.notes)])];saved.pool=saved.pool.filter(id=>champ(id));saved.recents=Array.isArray(saved.recents)?saved.recents.filter(id=>champ(id)):[];persist('pool');
const state={tab:'explore',query:'',filter:'Todos',itemQuery:'',itemGroup:'Todos',itemScope:'all',itemTier:'Todos',itemChamp:'Todos',sort:'name',detail:null,phase:0,form:'rhaast',compare:[]};
const nav=[['explore','Explorar','search'],['pool','Mi pool','pool'],['items','Objetos','items'],['study','Estudio','study']];
const R=window.MaverickRoster.create({D,saved,esc,icon,persist,render,toast,navigate,openChampion,getTab:()=>state.tab,openChampionItems:id=>{state.itemChamp=id;state.itemScope='all';state.itemGroup='Todos';state.itemTier='Todos';state.itemQuery='';navigate('items');}});
let toastTimer;
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),2700);}
function navigate(tab){if(!nav.some(n=>n[0]===tab))tab='explore';state.tab=tab;location.hash=tab;render();window.scrollTo({top:0,behavior:'instant'});}
function render(){
 $('#version').textContent=D.version;
 for(const selector of ['.desktop-nav','.bottom-nav'])$(selector).innerHTML=nav.map(([id,label,i])=>`<button class="nav-button ${state.tab===id?'active':''}" data-action="navigate" data-tab="${id}" ${state.tab===id?'aria-current="page"':''}>${icon(i)}<span>${label}</span><span class="nav-number">${id==='explore'?D.champions.length:id==='pool'?saved.pool.length:id==='items'?D.items.length:'↗'}</span></button>`).join('');
 $('#breadcrumb').textContent=({explore:'Todos los campeones',pool:'Mi pool',items:'Wiki de objetos',study:'Mi estudio'})[state.tab];
 $('#main').innerHTML=state.tab==='explore'?R.explorePage():state.tab==='pool'?R.poolPage():state.tab==='items'?itemsPage():studyPage();
}
function search(value,kind){return `<div class="search-wrap">${icon('search')}<input class="search-input" type="search" autocomplete="off" data-search="${kind}" value="${esc(value)}" aria-label="${kind==='pool'?'Buscar campeón':'Buscar objeto'}" placeholder="${kind==='pool'?'Buscar campeón, clase o estilo…':'Buscar objeto, estadística o efecto…'}"></div>`;}
function badge(c){const css=c.build==='AP'?'ap':c.build.includes('híbrido')||c.build==='Híbrido'?'hybrid':'ad';return`<span class="tag ${css}">${esc(c.build)}</span><span class="tag muted">${esc(c.role.split(' / ')[0])}</span>`;}
function card(c){return R.card(c);}
function shortStat(s){const names={ad:'AD',ap:'AP',hp:'vida',armor:'armadura',mr:'RM',as:'vel. ataque',haste:'aceleración',lethality:'letalidad',armorpen:'pen. armadura',magicpen:'pen. mágica',speed:'movimiento',lifesteal:'robo de vida',crit:'crítico',mana:'maná'};return names[s.key]?`${s.value}${s.percent?'%':''} ${names[s.key]}`:s.text;}
function itemCard(i){return`<article class="item-card"><button class="item-head" data-action="item" data-id="${i.id}"><img src="assets/items/${i.id}.png" alt="" loading="lazy" width="45" height="45"><span><h3>${esc(i.name)}</h3><small>${i.cost.toLocaleString('es-CL')} oro</small></span></button><div class="item-stats">${i.stats.slice(0,4).map(s=>`<span class="stat-pill">${esc(shortStat(s))}</span>`).join('')||'<span class="stat-pill">Ver efecto</span>'}</div><p class="item-desc">${esc(i.effects.replace(/\n+/g,' · ').slice(0,135))}</p><div class="item-bottom"><small>${i.recommendedBy.length?`${i.recommendedBy.length} perfiles`:(i.tier==='Completo'?'Alternativa':'Componente / utilidad')}</small><button class="text-button" data-action="item" data-id="${i.id}">Ver ${icon('arrow')}</button><button class="tiny-button" data-action="add-build" data-id="${i.id}" aria-label="Añadir ${esc(i.name)} a mi build">${icon('plus')}</button></div></article>`;}
function filteredItems(){const q=normalize(state.itemQuery);return D.items.filter(i=>(state.itemScope!=='pool'||i.recommendedBy.some(id=>saved.pool.includes(id)))&&(state.itemGroup==='Todos'||i.groups.includes(state.itemGroup))&&(state.itemTier==='Todos'||i.tier===state.itemTier)&&(state.itemChamp==='Todos'||i.recommendedBy.includes(state.itemChamp))&&normalize([i.name,i.aliases,...i.stats.map(s=>s.text),i.effects].join(' ')).includes(q)).sort((a,b)=>state.sort==='price-up'?a.cost-b.cost:state.sort==='price-down'?b.cost-a.cost:a.name.localeCompare(b.name,'es'));}
function itemResults(){const items=filteredItems();return{count:items.length,html:items.length?items.map(itemCard).join(''):`<div class="empty">${icon('search')}<b>Ningún objeto coincide.</b>Prueba con «Todos los objetos» o limpia los filtros.<br><button class="text-button" data-action="reset-items">Limpiar filtros ${icon('arrow')}</button></div>`};}
function itemsPage(){const result=itemResults();return`<div class="fade-in"><div class="page-heading"><div><div class="eyebrow">ELIGE LO QUE TU PARTIDA NECESITA</div><h1>Arsenal de la Grieta.</h1><p>Estadísticas, recetas y opciones para tu champion pool.</p></div><button class="secondary" data-action="build">${icon('items')} Mi build (${saved.build.length}/6)</button></div><div class="wiki-intro">${icon('gem')}<div><b>Datos oficiales. Decisiones tuyas.</b><p>Riot Data Dragon ${D.version} · ${D.items.length} objetos · Español LATAM</p></div><button class="text-button" data-action="export-items">Exportar wiki .txt ${icon('download')}</button></div><div class="toolbar">${search(state.itemQuery,'items')}<div class="chips">${[['pool','Opciones para mi pool'],['all','Todos los objetos']].map(([s,label])=>`<button class="chip ${state.itemScope===s?'active':''}" data-action="scope" data-scope="${s}">${label}</button>`).join('')}</div></div><div class="chips">${['Todos','AD','AP','Ataques','Defensa','Aceleración','Letalidad','Botas'].map(g=>`<button class="chip ${state.itemGroup===g?'active':''}" data-action="item-group" data-group="${g}">${g}</button>`).join('')}</div><div class="item-controls" style="margin-top:14px"><select class="select" data-select="itemChamp" aria-label="Filtrar objetos por campeón"><option value="Todos">Todos los campeones</option>${D.champions.map(c=>`<option value="${c.id}" ${state.itemChamp===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select><select class="select" data-select="itemTier" aria-label="Tipo de objeto">${['Todos','Completo','Componente','Básico','Especial'].map(t=>`<option ${state.itemTier===t?'selected':''}>${t}</option>`).join('')}</select><select class="select" data-select="sort" aria-label="Ordenar objetos">${[['name','Nombre A–Z'],['price-up','Menor precio'],['price-down','Mayor precio']].map(([v,l])=>`<option value="${v}" ${state.sort===v?'selected':''}>${l}</option>`).join('')}</select>${state.compare.length?`<button class="secondary" data-action="compare">Comparar (${state.compare.length}/2)</button>`:''}</div><div class="results-line"><span id="item-count">${result.count} objetos encontrados</span><span>Opciones orientativas · PC / Grieta</span></div><div class="item-grid" id="item-grid">${result.html}</div></div>`;}
function studyPage(){const favorites=D.champions.filter(c=>saved.favorites.includes(c.id));const notes=Object.entries(saved.notes).filter(([id,n])=>champ(id)&&String(n).trim());return`<div class="fade-in"><div class="page-heading"><div><div class="eyebrow">TU CONOCIMIENTO, A TU RITMO</div><h1>Mi estudio.</h1><p>Guarda lo que aprendes y vuelve a lo que importa.</p></div><span class="subtle-badge">${icon('shield')} Guardado en este dispositivo</span></div><div class="study-stats"><div class="study-stat"><b>${saved.favorites.length}</b><span>Favoritos</span></div><div class="study-stat"><b>${saved.studied.length}<span> / ${D.champions.length}</span></b><span>Campeones estudiados</span></div><div class="study-stat"><b>${notes.length}</b><span>Fichas con notas</span></div></div><div class="study-actions"><button class="secondary" data-action="export-guide">${icon('download')} Mi pool .txt</button><button class="secondary" data-action="export-items">${icon('download')} Wiki de objetos .txt</button><button class="secondary" data-action="export-notes">${icon('edit')} Mis notas .txt</button></div><div class="section-line"><h2>Tu selección</h2><small>${favorites.length} favoritos</small></div><div class="champ-grid">${favorites.length?favorites.map(card).join(''):'<div class="empty"><b>Haz tuyo este cuaderno.</b>Guarda campeones con la estrella y escribe tus notas en cada ficha.</div>'}</div>${notes.length?`<div class="section-line"><h2>Notas de la Grieta</h2></div>${notes.map(([id,n])=>`<article class="saved-note"><button class="text-button saved-note-head" data-action="champion" data-id="${id}"><img src="assets/portraits/${id}.png" alt="">${esc(champ(id).name)} ${icon('arrow')}</button><p>${esc(n)}</p></article>`).join('')}`:''}<div class="section-line"><h2>Hablar el idioma de los objetos</h2></div><div class="glossary-grid">${D.glossary.map(([k,title,text])=>`<article class="glossary-card"><b>${esc(k)}</b><small>${esc(title)}</small><p>${esc(text)}</p></article>`).join('')}</div><div class="sources"><b>Sobre los datos</b><p>Estadísticas y precios: Riot Data Dragon ${D.version}, descargados el 10/11/2026. Las prioridades y el perfil de escalado son orientación editorial; no son una medición de winrate. Las compras cambian según parche, ruta y enemigos. La app estudia LoL PC, no Wild Rift.</p><p>AD y AP, tipo de daño y clase son conceptos distintos. Los ejemplos de cada etapa son alternativas; no hay que comprarlos todos. Los valores dinámicos ausentes del catálogo se indican sin inventar cifras.</p>${D.sources.map(s=>`<a href="${s.url}" target="_blank" rel="noopener">${esc(s.name)} ↗</a>`).join('')}<p>Proyecto independiente sin afiliación con Riot Games. League of Legends y sus recursos pertenecen a Riot Games. El pool, notas y favoritos se guardan localmente; exporta tus notas antes de borrar los datos de la app.</p></div></div>`;}
function openChampion(id,reset=true){const c=champ(id);if(!c)return;if(reset){state.phase=0;state.form='rhaast';R.recordRecent(id);}state.detail=id;
 const form=c.forms?.[state.form];
 $('#dialog-content').innerHTML=`<div class="detail-top"><img src="assets/champions/${id}.jpg" alt=""><button class="icon-button close-detail" data-action="close-detail" aria-label="Cerrar ficha">${icon('close')}</button><div class="detail-heading"><small>${esc(c.title).toUpperCase()}</small><h2>${esc(c.name)}</h2><div class="tags">${badge(c)}<span class="tag muted">${esc(c.style)}</span></div></div></div><div class="detail-body">${R.detail(c)}<div class="identity"><div><small>Qué suele comprar</small><b>${esc(form?.build||c.build)}</b></div><div><small>Qué daño hace</small><b>${esc(c.damage)}</b></div><div><small>Identidad de combate</small><b>${esc(form?.role||c.role)}</b></div></div><h3>Cómo escala</h3><p>${esc(c.summary)}</p><div class="curve">${c.curve.map((v,i)=>`<div><span>${['INICIO','MEDIO','FINAL'][i]}</span><b>${esc(v)}</b></div>`).join('')}</div><p class="caption">Perfil orientativo, no una puntuación de poder. Objetos, ventaja y composición cambian la pelea.</p><div class="rule"><small>REGLA DE COMPRA</small>${esc(c.rule)}</div>${c.forms?`<div class="forms">${Object.entries(c.forms).map(([key,f])=>`<button data-action="form" data-form="${key}" class="${state.form===key?'active':''}">${esc(f.name)}</button>`).join('')}</div>`:''}<h3>Qué privilegiar en cada etapa</h3><div class="phase-tabs" role="tablist" aria-label="Etapas de la partida">${['Inicio','Medio','Final'].map((l,i)=>`<button role="tab" aria-selected="${state.phase===i}" aria-controls="phase-content" class="${state.phase===i?'active':''}" data-action="phase" data-phase="${i}">${l}</button>`).join('')}</div><div id="phase-content" role="tabpanel">${phaseContent(c)}</div><h3>Tu lectura de la partida</h3><label class="caption" for="champ-note">Anota lo que te funcionó, contra quién y por qué.</label><textarea class="note-area" id="champ-note" maxlength="12000" data-note="${id}" placeholder="Ej.: contra doble AP adelanté resistencia mágica antes del tercer objeto…">${esc(saved.notes[id]||'')}</textarea><div class="detail-actions"><button class="secondary" data-action="studied" data-id="${id}">${icon('check')} ${saved.studied.includes(id)?'Estudiado ✓':'Marcar como estudiado'}</button><button class="secondary" data-action="export-champion" data-id="${id}">${icon('download')} Exportar ficha .txt</button></div><p class="caption" id="note-status">Notas guardadas en este dispositivo. Las etapas dependen de niveles y objetos, no de un minuto fijo.</p></div>`;
 if(!$('#detail-dialog').open)$('#detail-dialog').showModal();if(reset)$('#detail-dialog').scrollTop=0;
}
function phaseContent(c){const s=(c.forms?.[state.form]?.stages||c.stages)[state.phase];return`<section class="phase-card"><h4>${esc(s.focus)}</h4><div class="priorities">${s.priorities.map(p=>`<span class="priority">${esc(p)}</span>`).join('')}</div><p>${esc(s.reason)}</p><p class="caption">OPCIONES DE OBJETOS · SON ALTERNATIVAS, NO UNA LISTA OBLIGATORIA</p><div class="option-list">${s.items.map(id=>option(byId(id))).join('')}</div><div class="adapt"><b>Adapta la compra:</b> ${esc(s.adapt)}</div></section>`;}
function option(i){if(!i)return'';return`<button class="option" data-action="item" data-id="${i.id}"><img src="assets/items/${i.id}.png" alt="" width="39" height="39"><span><b>${esc(i.name)}</b><small>${i.cost.toLocaleString('es-CL')} oro · ${esc(i.stats.slice(0,2).map(shortStat).join(' / '))}</small></span>${icon('arrow')}</button>`;}
function recipe(id){const i=byId(id);return i?`<button class="recipe" data-action="item" data-id="${id}"><img src="assets/items/${id}.png" alt="">${esc(i.name)}</button>`:'';}
function showItem(content){$('#item-content').innerHTML=content;if(!$('#item-dialog').open)$('#item-dialog').showModal();$('#item-dialog').scrollTop=0;}
function openItem(id){const i=byId(id);if(!i)return;showItem(`<div class="item-modal-body"><div class="modal-topline"><img src="assets/items/${id}.png" alt=""><div><h2>${esc(i.name)}</h2><div class="gold">${i.cost.toLocaleString('es-CL')} oro <span class="caption">· venta ${i.sell} · ${esc(i.tier)}</span></div></div><button class="icon-button" data-action="close-item" aria-label="Cerrar objeto">${icon('close')}</button></div><div class="large-stats">${i.stats.map(s=>`<div class="large-stat">${esc(s.text)}</div>`).join('')||'<div class="large-stat">Objeto de utilidad</div>'}</div><div class="effect-text">${esc(i.effects||'Consulta las mejoras y componentes disponibles.')}</div>${i.dynamic?'<p class="caption">La fuente no incluye algunas cifras calculadas en partida. Se muestran como [valor dinámico] para evitar confundirlas con cero.</p>':''}${i.from.length?`<h3 class="modal-section-title">Se construye con</h3><div class="mini-recipes">${i.from.map(recipe).join('')}</div>`:''}${i.into.length?`<h3 class="modal-section-title">Puede mejorar a</h3><div class="mini-recipes">${i.into.map(recipe).join('')}</div>`:''}<h3 class="modal-section-title">Perfiles orientativos (${i.recommendedBy.length})</h3><p class="caption">Se muestran hasta 18 perfiles. Consulta los objetos desde la ficha del campeón para filtrar por él.</p><div class="item-users">${i.recommendedBy.slice(0,18).map(id=>`<button class="item-user" data-action="item-champion" data-id="${id}"><img src="assets/portraits/${id}.png" alt="">${esc(champ(id).name)}</button>`).join('')||'<span class="caption">Consulta general: no está destacado en las rutas editoriales del pool.</span>'}</div><div class="modal-footer"><button class="primary" data-action="add-build" data-id="${id}">${icon('plus')} Añadir a mi build</button><button class="secondary" data-action="toggle-compare" data-id="${id}">${icon('compare')} ${state.compare.includes(id)?'Quitar de comparación':'Comparar objeto'}</button>${state.compare.length===2?'<button class="secondary" data-action="compare">Ver comparación →</button>':''}</div><p class="caption">Riot Data Dragon ${D.version} · Grieta del Invocador / PC</p></div>`);}
function showBuild(){const items=saved.build.map(byId);const totals={};for(const i of items)for(const s of i.stats)if(s.key!=='other'&&s.key!=='regen'&&s.key!=='speed'){const k=s.key+':'+s.percent;totals[k]??={...s,value:0};totals[k].value+=s.value;}showItem(`<div class="item-modal-body"><div class="modal-topline"><div><h2>Tu build de estudio</h2><div class="gold">${items.reduce((s,i)=>s+i.cost,0).toLocaleString('es-CL')} oro · ${items.length}/6 espacios</div></div><button class="icon-button" data-action="close-item" aria-label="Cerrar build">${icon('close')}</button></div>${items.map((i,n)=>`<div class="build-slot"><img src="assets/items/${i.id}.png" alt=""><span>${esc(i.name)}<small>${i.cost} oro</small></span><button class="icon-button" data-action="remove-build" data-index="${n}" aria-label="Quitar ${esc(i.name)}">${icon('trash')}</button></div>`).join('')||'<div class="empty"><b>Cada espacio es una decisión.</b>Añade objetos desde la wiki para explorar sus estadísticas.</div>'}<div class="item-stats">${Object.values(totals).map(s=>`<span class="stat-pill">${esc(shortStat(s))}</span>`).join('')}</div><p class="caption">Suma de estadísticas base, sin habilidades, pasivas, bonificaciones porcentuales adicionales ni reglas de exclusión. Es un borrador de estudio; no valida restricciones de compra del juego.</p><button class="secondary" data-action="export-build">${icon('download')} Exportar build .txt</button></div>`);}
function compare(){if(state.compare.length<2){toast('Abre otro objeto y añádelo para comparar dos.');return;}const items=state.compare.map(byId);const rows=[...new Set(items.flatMap(i=>i.stats.map(s=>s.key)))];showItem(`<div class="item-modal-body"><div class="modal-topline"><div><h2>Comparar decisiones</h2><p class="caption">Estadísticas base oficiales. Los efectos también importan.</p></div><button class="icon-button" data-action="close-item" aria-label="Cerrar comparación">${icon('close')}</button></div><div class="comparison"><table><thead><tr><th>Estadística</th>${items.map(i=>`<th>${esc(i.name)}</th>`).join('')}</tr></thead><tbody><tr><td>Precio</td>${items.map(i=>`<td>${i.cost} oro</td>`).join('')}</tr>${rows.map(key=>`<tr><td>${esc(({ad:'AD',ap:'AP',hp:'Vida',armor:'Armadura',mr:'RM',haste:'Aceleración',as:'Vel. ataque'})[key]||key)}</td>${items.map(i=>`<td>${i.stats.filter(s=>s.key===key).map(s=>`${s.value}${s.percent?'%':''}`).join(' / ')||'—'}</td>`).join('')}</tr>`).join('')}</tbody></table></div>${items.map(i=>`<h3 class="modal-section-title">${esc(i.name)}</h3><div class="effect-text">${esc(i.effects)}</div>`).join('')}<button class="text-button" data-action="clear-compare">Limpiar comparación ${icon('close')}</button></div>`);}
function addBuild(id){if(saved.build.length>=6){toast('Tu borrador ya tiene 6 objetos. Quita uno para añadir otro.');return;}saved.build.push(id);persist('build');toast('Objeto añadido a tu build de estudio');if(state.tab==='items')render();}
function exportText(name,text){if(window.Android?.exportText){window.Android.exportText(name,text);return;}const a=document.createElement('a');const url=URL.createObjectURL(new Blob(['\ufeff'+text],{type:'text/plain;charset=utf-8'}));a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),3000);toast('Archivo de texto preparado');}
function championText(c){const list=c.forms?Object.values(c.forms).flatMap(f=>['\nRUTA: '+f.name,...f.stages.flatMap((s,n)=>stageText(s,n))]):c.stages.flatMap((s,n)=>stageText(s,n));return[c.name,`Build: ${c.build} | Daño: ${c.damage} | Clase: ${c.role}`,'',c.summary,'','REGLA: '+c.rule,...list,'\nMIS NOTAS',saved.notes[c.id]||'Sin notas.','\nFuente de estadísticas: Riot Data Dragon '+D.version,'Prioridades: orientación editorial, no una lista obligatoria.'].join('\r\n');}
function stageText(s,n){return['\n'+['INICIO','MEDIO','FINAL'][n]+': '+s.focus,'Prioriza: '+s.priorities.join(' + '),s.reason,'Opciones: '+s.items.map(id=>byId(id)?.name||id).join(' / '),'Ajuste: '+s.adapt];}
function allGuideText(){return['LoL Maverick Study Proyect','Mi pool de estudio · Datos '+D.version,'AD/AP son estadísticas; físico/mágico son tipos de daño; luchador/asesino son clases.','',...D.champions.filter(c=>saved.pool.includes(c.id)).map(championText),'\nGLOSARIO',...D.glossary.map(g=>g.join(' — '))].join('\r\n\r\n');}
function allItemText(){return['LoL Maverick Study Proyect — Wiki de objetos','Riot Data Dragon '+D.version,'',...D.items.map(i=>[i.name+' ['+i.id+']',`Compra: ${i.cost} oro | Venta: ${i.sell}`,i.stats.map(s=>s.text).join('\r\n'),i.effects,'Componentes: '+i.from.map(id=>byId(id).name).join(' / '),'Mejoras: '+i.into.map(id=>byId(id).name).join(' / ')].join('\r\n'))].join('\r\n\r\n');}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action,id=b.dataset.id;if(a.startsWith('roster-')){R.click(a,b);return;}
 switch(a){case'navigate':navigate(b.dataset.tab);break;case'champion':openChampion(id);break;case'favorite':{const n=saved.favorites.indexOf(id);n<0?saved.favorites.push(id):saved.favorites.splice(n,1);persist('favorites');render();break;}case'item':openItem(id);break;case'close-detail':$('#detail-dialog').close();break;case'close-item':$('#item-dialog').close();break;case'phase':state.phase=Number(b.dataset.phase);document.querySelectorAll('.phase-tabs button').forEach((el,n)=>{el.classList.toggle('active',n===state.phase);el.setAttribute('aria-selected',String(n===state.phase));});$('#phase-content').innerHTML=phaseContent(champ(state.detail));break;case'form':{const scroll=$('#detail-dialog').scrollTop;state.form=b.dataset.form;openChampion(state.detail,false);$('#detail-dialog').scrollTop=scroll;break;}case'studied':{const n=saved.studied.indexOf(id);n<0?saved.studied.push(id):saved.studied.splice(n,1);persist('studied');b.innerHTML=icon('check')+(saved.studied.includes(id)?' Estudiado ✓':' Marcar como estudiado');render();break;}case'scope':state.itemScope=b.dataset.scope;render();break;case'item-group':state.itemGroup=b.dataset.group;render();break;case'reset-items':Object.assign(state,{itemQuery:'',itemGroup:'Todos',itemScope:'all',itemTier:'Todos',itemChamp:'Todos'});render();break;case'item-champion':$('#item-dialog').close();openChampion(id);break;case'add-build':addBuild(id);break;case'build':showBuild();break;case'remove-build':saved.build.splice(Number(b.dataset.index),1);persist('build');showBuild();if(state.tab==='items')render();break;case'toggle-compare':{const n=state.compare.indexOf(id);if(n>=0)state.compare.splice(n,1);else if(state.compare.length<2)state.compare.push(id);else{toast('Ya hay dos objetos. Limpia la comparación para elegir otros.');return;}openItem(id);if(state.tab==='items')render();break;}case'compare':compare();break;case'clear-compare':state.compare=[];$('#item-dialog').close();if(state.tab==='items')render();break;case'export-champion':exportText(champ(id).name.replace(/[^\p{L}\p{N}]+/gu,'_')+'.txt',championText(champ(id)));break;case'export-guide':exportText('Champion_Pool_Guia.txt',allGuideText());break;case'export-items':exportText('Wiki_Objetos.txt',allItemText());break;case'export-notes':exportText('Mis_Notas_Maverick.txt',['LoL Maverick Study Proyect — Mis notas',...Object.entries(saved.notes).filter(([id,n])=>champ(id)&&n.trim()).map(([id,n])=>champ(id).name+'\r\n'+n)].join('\r\n\r\n'));break;case'export-build':exportText('Mi_Build_Maverick.txt',['LoL Maverick Study Proyect — Build de estudio',...saved.build.map(id=>{const i=byId(id);return i.name+' — '+i.cost+' oro\r\n'+i.stats.map(s=>s.text).join('\r\n');}),'Sin cálculo de pasivas ni validación de restricciones del juego.'].join('\r\n\r\n'));break;}
});
document.addEventListener('input',e=>{if(e.target.dataset.search==='roster'){R.input(e.target.value);return;}if(e.target.dataset.note){const id=e.target.dataset.note;saved.notes[id]=e.target.value;persist('notes');$('#note-status').textContent='Nota guardada en este dispositivo.';return;}if(e.target.dataset.search==='items'){state.itemQuery=e.target.value;const result=itemResults();$('#item-grid').innerHTML=result.html;$('#item-count').textContent=result.count+' objetos encontrados';}});
document.addEventListener('change',e=>{if(e.target.dataset.rosterSelect){R.change(e.target.dataset.rosterSelect,e.target.value);return;}if(e.target.dataset.select){state[e.target.dataset.select]=e.target.value;render();}});
for(const id of ['detail-dialog','item-dialog'])$('#'+id).addEventListener('click',e=>{if(e.target===$('#'+id)){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();}});
$('#detail-dialog').addEventListener('close',()=>{if(['study','explore','pool'].includes(state.tab))render();});
window.addEventListener('hashchange',()=>{const tab=location.hash.slice(1);if(tab!==state.tab)navigate(tab);});
window.maverickBack=()=>{if($('#item-dialog').open){$('#item-dialog').close();return true;}if($('#detail-dialog').open){$('#detail-dialog').close();return true;}if(state.tab!=='explore'){navigate('explore');return true;}return false;};
let installPrompt;window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;$('#install-button').hidden=false;$('#install-button').innerHTML=icon('download');});$('#install-button').addEventListener('click',async()=>{if(installPrompt){await installPrompt.prompt();installPrompt=null;$('#install-button').hidden=true;}});
if('serviceWorker'in navigator&&['http:','https:'].includes(location.protocol))navigator.serviceWorker.register('sw.js').catch(()=>{});
state.tab=nav.some(n=>n[0]===location.hash.slice(1))?location.hash.slice(1):'explore';render();
})();
